mapper.update:
UPDATE contract_payout
SET payout_status = #{nextStatus},
    processor = #{processor},
    approved_at = #{approvedAt}
WHERE payout_id = #{payoutId}
  AND payout_status = #{currentStatus}

UPDATE contract_payout
SET payout_status = #{nextStatus},
    paid_at = #{paidAt}
WHERE payout_id = #{payoutId}
  AND payout_status = #{currentStatus}

UPDATE contract_payout
SET payout_status = #{nextStatus},
    cancelled_at = #{cancelledAt}
WHERE payout_id = #{payoutId}
  AND payout_status IN ('CALCULATED', 'APPROVED')
